@startuml
' Synthetic diagram used by the tests
skinparam classAttributeIconSize 0

class Address

class Shipment

class Warehouse

class Receipt

interface PaymentGateway {
  +charge(order: Order): Receipt
}

enum OrderStatus {
  DRAFT
  PAID
  SHIPPED
}

class OrderLine {
  +quantity: int
}
' Orders and their lines
class Order {
  +id: OrderId
  +total(): Money
}
class Customer {
  +id: CustomerId
  +email: String
}
package Catalog {
  class Product {
    +id: ProductId
    +name: String
  }
  class Category {
    +name: String
  }
}

Customer "1" -- "*" Order
Order *-- "*" OrderLine
OrderLine --> Product
Product --> Category
Order --> OrderStatus
PaymentGateway ..> Order
PaymentGateway ..> Receipt
Shipment --> Order
Shipment --> Warehouse
Shipment --> Address
Customer --> Address
Warehouse --> Product
Receipt --> Customer
@enduml

